-- The arcade update's email, as a DRAFT in Emails (not sent, not scheduled): written to parents and educators, game names in bold.
update newsletters set data = data || $n${"intro": "<p>Dear parents and educators,</p><p>Big news from our Online Games page: eight games just got a brand-new arcade makeover, and every one now has a learning twist for kids from Kindergarten to 5th grade.</p><p>In <strong>Pathbuilder</strong>, kids now build a road from their house all the way to their car. When the road reaches it, the car drives the whole road home, a fun lesson in planning and engineering.</p><p><strong>Air Hockey</strong> is now a 3D table against Chike, with numbered pucks that keep kids adding as they play. <strong>Cosmic Blast!</strong> flies past all eight planets, with a fun fact about each one. <strong>Maze Quest</strong> lets kids race a friend online with a room code, and they can pick their own grade level, from Kindergarten to 5th. And <strong>DropBlox</strong> became <strong>Fruit Drop</strong>: match three fruit and set off juicy chains while spotting patterns.</p><p><strong>Spelling Detective</strong> and <strong>Balloon Pop Math</strong> now let kids pick their grade, with Chike there to give hints, and <strong>Bounce &amp; Bank</strong> and <strong>Memory Match</strong> have a fresh new look.</p><p>In the Subscriber&#39;s Portal you&#39;ll find a short moving preview of every game, what changed, and what kids learn while they play.</p><p>And <strong>Doodle Dash</strong> is still our most popular game. Ask your young creator to draw their own level!</p>", "body": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><meta name=\"color-scheme\" content=\"light\"><meta name=\"supported-color-schemes\" content=\"light\"><title>8 games just got an arcade makeover</title><style>body,table,td,a{-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;}table,td{mso-table-lspace:0pt;mso-table-rspace:0pt;}img{-ms-interpolation-mode:bicubic;border:0;height:auto;line-height:100%;outline:none;text-decoration:none;}@media screen and (max-width:600px){.container{width:100%!important;}.headline{font-size:23px!important;}}</style></head><body style=\"margin:0;padding:0;background:#FAF4E6;\"><div style=\"display:none;max-height:0;overflow:hidden;opacity:0;font-size:1px;line-height:1px;color:#FAF4E6;\">Fruit Drop, a Maze Quest race, 3D Air Hockey and more. Come see what&#39;s new.</div><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" bgcolor=\"#FAF4E6\" style=\"background:#FAF4E6;background-image:linear-gradient(180deg,#E2EDEF 0%,#EEF4F3 26%,#FAF4E6 66%,#FDF8EC 100%);\"><tr><td align=\"center\" style=\"padding:28px 16px;\"><table role=\"presentation\" class=\"container\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:600px;max-width:600px;\"><tr><td style=\"padding:8px 24px 20px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr><td valign=\"middle\" width=\"120\"><img src=\"https://www.chikescreativespace.com/assets/brand/logo-email.png\" width=\"120\" height=\"64\" alt=\"Chike&#39;s Creative Space\" style=\"display:block;width:120px;height:64px;\"></td><td valign=\"middle\" align=\"right\" style=\"font-family:Arial,Helvetica,sans-serif;font-size:12px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;\"><a href=\"https://www.chikescreativespace.com/#/watch\" style=\"color:#1E2226;text-decoration:none;margin-left:14px;\">Watch</a><a href=\"https://www.chikescreativespace.com/#/create\" style=\"color:#1E2226;text-decoration:none;margin-left:14px;\">Make</a><a href=\"https://www.chikescreativespace.com/#/stories\" style=\"color:#1E2226;text-decoration:none;margin-left:14px;\">Read</a><a href=\"https://www.chikescreativespace.com/#/play\" style=\"color:#1E2226;text-decoration:none;margin-left:14px;\">Play</a></td></tr></table></td></tr><tr><td style=\"padding:4px 24px 0;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr><td style=\"border:2px solid #1E2226;border-radius:16px;overflow:hidden;\"><img src=\"https://www.chikescreativespace.com/assets/newsletter/arcade-update/reel.gif\" width=\"600\" alt=\"A moving preview of eight games: Spelling Detective, Cosmic Blast!, Bounce and Bank, Air Hockey Arcade, Balloon Pop Math, Maze Quest, Fruit Drop and Memory Match\" style=\"display:block;width:100%;height:auto;\"></td></tr></table></td></tr><tr><td style=\"padding:24px 24px 0;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#FFFBF3;border:2px solid #1E2226;border-radius:16px;\"><tr><td style=\"padding:28px 24px;font-family:Arial,Helvetica,sans-serif;\"><p style=\"margin:0 0 10px;font-size:12px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:#8A6D00;\">NEW IN THE ARCHIVE</p><h1 class=\"headline\" style=\"margin:0 0 16px;font-size:28px;line-height:1.25;font-weight:800;color:#1E2226;\">Eight Games, One Big Arcade Makeover</h1><div style=\"font-size:16px;line-height:1.65;color:#1E2226;\"><p>Dear parents and educators,</p><p>Big news from our Online Games page: eight games just got a brand-new arcade makeover, and every one now has a learning twist for kids from Kindergarten to 5th grade.</p><p>In <strong>Pathbuilder</strong>, kids now build a road from their house all the way to their car. When the road reaches it, the car drives the whole road home, a fun lesson in planning and engineering.</p><p><strong>Air Hockey</strong> is now a 3D table against Chike, with numbered pucks that keep kids adding as they play. <strong>Cosmic Blast!</strong> flies past all eight planets, with a fun fact about each one. <strong>Maze Quest</strong> lets kids race a friend online with a room code, and they can pick their own grade level, from Kindergarten to 5th. And <strong>DropBlox</strong> became <strong>Fruit Drop</strong>: match three fruit and set off juicy chains while spotting patterns.</p><p><strong>Spelling Detective</strong> and <strong>Balloon Pop Math</strong> now let kids pick their grade, with Chike there to give hints, and <strong>Bounce &amp; Bank</strong> and <strong>Memory Match</strong> have a fresh new look.</p><p>In the Subscriber&#39;s Portal you&#39;ll find a short moving preview of every game, what changed, and what kids learn while they play.</p><p>And <strong>Doodle Dash</strong> is still our most popular game. Ask your young creator to draw their own level!</p></div><div style=\"margin-top:24px;\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\"><tr><td bgcolor=\"#1273B0\" style=\"border-radius:999px;background:#1273B0;\"><a href=\"https://www.chikescreativespace.com/newsletter/arcade-makeover?k=__ACCESS_KEY__\" style=\"display:inline-block;padding:14px 30px;font-family:Arial,Helvetica,sans-serif;font-size:15px;font-weight:800;color:#FFFFFF;text-decoration:none;border-radius:999px;\">See the new games</a></td></tr></table></div></td></tr></table></td></tr><tr><td style=\"padding:28px 24px;font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:1.7;color:#5B6673;text-align:center;\"><p style=\"margin:0 0 8px;font-size:14px;font-weight:700;color:#1E2226;\">For the latest updates, follow us on</p><p style=\"margin:0 0 22px;\"><a href=\"https://www.youtube.com/@ChikesCreativeSpace\" style=\"display:inline-block;margin:4px 9px;color:#1E2226;font-size:14px;font-weight:700;text-decoration:none;\"><img src=\"https://www.chikescreativespace.com/assets/brand/social-youtube.png\" width=\"32\" height=\"32\" alt=\"\" style=\"vertical-align:middle;border:0;margin-right:8px;\">YouTube</a><a href=\"https://www.facebook.com/chikescreativespace\" style=\"display:inline-block;margin:4px 9px;color:#1E2226;font-size:14px;font-weight:700;text-decoration:none;\"><img src=\"https://www.chikescreativespace.com/assets/brand/social-facebook.png\" width=\"32\" height=\"32\" alt=\"\" style=\"vertical-align:middle;border:0;margin-right:8px;\">Facebook</a><a href=\"https://www.instagram.com/chikescreativespace/\" style=\"display:inline-block;margin:4px 9px;color:#1E2226;font-size:14px;font-weight:700;text-decoration:none;\"><img src=\"https://www.chikescreativespace.com/assets/brand/social-instagram.png\" width=\"32\" height=\"32\" alt=\"\" style=\"vertical-align:middle;border:0;margin-right:8px;\">Instagram</a></p><p style=\"margin:0 0 6px;\"><a href=\"https://www.chikescreativespace.com\" style=\"color:#1E2226;font-weight:700;text-decoration:none;\">www.chikescreativespace.com</a></p><p style=\"margin:0 0 6px;\">Questions? <a href=\"mailto:info@chikescreativespace.com\" style=\"color:#1E2226;\">info@chikescreativespace.com</a></p><p style=\"margin:0 0 6px;font-weight:700;\">3343 Peachtree Rd NE., Ste 180 #A2067, Atlanta, GA 30326</p><p style=\"margin:0 0 6px;\">You’re receiving this because you signed up for Chike’s Creative Space updates.</p><p style=\"margin:0 0 6px;\"><a href=\"https://www.chikescreativespace.com/newsletter?k=__ACCESS_KEY__\" style=\"color:#1E2226;font-weight:700;\">Subscriber’s Portal</a> &ndash; stories, videos and launches just for subscribers</p><p style=\"margin:0;\"><a href=\"__UNSUB_URL__\" style=\"color:#5B6673;text-decoration:underline;\">Unsubscribe</a></p></td></tr></table></td></tr></table></body></html>"}$n$::jsonb || jsonb_build_object('updatedAt', to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), updated_at = now()
where id = 'news-arcade-update' and data->>'status' = 'draft';
